import java.sql.*;

public class DatabaseConnection {
    private static final String DB_URL = "jdbc:mysql://localhost:3306/myDatabase";
    private static final String USER = "user_from_config"; // Read from a secure configuration file
    private static final String PASS = "password_from_config"; // Read from a secure configuration file

